import heapq

def find_path(graph, start, goal):
    if start == goal:
        return [start]
    priority_queue = [(0, start)]
    visited = set()
    while priority_queue:
        current_cost, current_node = heapq.heappop(priority_queue)
        if current_node in visited:
            continue
        visited.add(current_node)
        if current_node == goal:
            path = [current_node]
            while current_node in graph:
                current_node = graph[current_node][-1]
                path.append(current_node)
            return path[::-1]
        for neighbor in graph.get(current_node, []):
            if neighbor not in visited:
                g_score = current_cost + 1
                h_score = heuristic_estimate(graph, neighbor, goal)
                f_score = g_score + h_score
                heapq.heappush(priority_queue, (f_score, neighbor))
    return None

def heuristic_estimate(graph, node, goal):
    return len(graph[node]) + len(graph[goal]) - 1
