import heapq

def find_path(graph, start, goal):
    priority_queue = []
    heapq.heappush(priority_queue, (0, [start], start))
    visited = set()
    while priority_queue:
        cost, path, node = heapq.heappop(priority_queue)
        if node == goal:
            return path
        if node in visited:
            continue
        visited.add(node)
        for neighbor in graph.get(node, []):
            if neighbor not in visited:
                new_path = path + [neighbor]
                heapq.heappush(priority_queue, (cost + 1, new_path, neighbor))
    return None

